<?php
declare(strict_types=1);

require __DIR__ . '/app/bootstrap.php';
$providerId=(int)($_GET['id']??0); $profile=provider_public_profile($providerId);
if(!$profile){http_response_code(404);require __DIR__.'/templates/error-404.php';exit;}
$pageTitle=$profile['full_name']; $pageDescription=$profile['headline']?:'Perfil de proveedor aprobado en '.site_name(); $activeNav='providers';
require __DIR__.'/templates/header.php';
?>
<section class="section section-soft"><div class="container"><div class="profile-hero"><span class="avatar"><?=e(user_initials($profile['full_name']))?></span><div><span class="status status-success">Perfil aprobado</span><h1><?=e($profile['full_name'])?></h1><p><?=e($profile['headline']?:'Proveedor de servicios')?></p></div><div class="profile-score"><?php if((int)$profile['review_count']>0):?><strong><?=e(number_format((float)$profile['rating_avg'],1))?></strong><span><?= (int)$profile['review_count']?> reseña<?= (int)$profile['review_count']===1?'':'s'?></span><?php else:?><strong>Nuevo</strong><span>Sin reseñas aún</span><?php endif;?></div></div>
<div class="profile-content"><section class="panel"><div class="panel-header"><h2>Experiencia profesional</h2></div><div class="panel-body"><p class="muted"><?=nl2br(e($profile['bio']?:'El proveedor aún no agregó una descripción pública.'))?></p><div class="detail-list"><div class="detail-row"><span>Experiencia declarada</span><strong><?= (int)$profile['years_experience']?> año<?= (int)$profile['years_experience']===1?'':'s'?></strong></div><div class="detail-row"><span>Disponibilidad</span><strong><?=e($profile['availability_text']?:'Por coordinar')?></strong></div></div><h3>Servicios</h3><div class="chip-row"><?php foreach($profile['categories'] as $category):?><span class="chip"><?=e($category['name'])?></span><?php endforeach;?></div><h3>Distritos</h3><div class="chip-row"><?php foreach($profile['districts'] as $district):?><span class="chip"><?=e($district['name'])?></span><?php endforeach;?></div></div></section>
<aside><div class="panel"><div class="panel-header"><h2>Solicitar una propuesta</h2></div><div class="panel-body"><p class="muted text-small">Publica el trabajo dentro de la plataforma. Tus datos se protegen hasta que elijas una propuesta.</p><?php if(is_role('client')):?><a class="btn btn-primary btn-block" href="<?=e(url('request-new.php?provider='.$providerId))?>">Crear solicitud</a><?php elseif(!is_authenticated()):?><a class="btn btn-primary btn-block" href="<?=e(url('register.php?role=client'))?>">Crear cuenta de cliente</a><?php else:?><a class="btn btn-secondary btn-block" href="<?=e(url('dashboard.php'))?>">Volver a mi panel</a><?php endif;?></div></div></aside></div>
<?php if($profile['reviews']!==[]):?><section class="panel"><div class="panel-header"><h2>Reseñas publicadas</h2></div><div class="panel-body proposal-list"><?php foreach($profile['reviews'] as $review):?><article class="proposal-card"><div class="rating"><?=icon('star')?><?= (int)$review['rating']?>/5 · <?=e(date_pe($review['created_at']))?></div><p><?=e($review['comment']?:'El cliente no dejó comentario.')?></p></article><?php endforeach;?></div></section><?php endif;?></div></section>
